import { Page } from './types';
import { TemplateEngine } from './templates';

export interface BuildContext {
  config: SsgConfig;
  pages: Page[];
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  engine?: TemplateEngine;
  port?: number;
  [key: string]: any;
}

export interface Plugin {
  name: string;
  onStart?(context: BuildContext): Promise<void> | void;
  beforeBuild?(context: BuildContext): Promise<void> | void;
  onFile?(page: Page, context: BuildContext): Promise<void> | void;
  afterBuild?(context: BuildContext): Promise<void> | void;
  onEnd?(context: BuildContext): Promise<void> | void;
}

export interface SsgConfig {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  port?: number;
  plugins?: (string | Plugin)[];
}

import { Plugin, BuildContext } from '../src/plugin';
import { parseMarkdownFiles } from '../src/parser';

export const MarkdownPlugin: Plugin = {
  name: 'markdown',

  beforeBuild(context: BuildContext): void {
    context.pages = parseMarkdownFiles(context.contentDir);
  },
};

import fs from 'fs';
import path from 'path';
import { Plugin, BuildContext } from '../src/plugin';
import { TemplateEngine } from '../src/templates';
import { Page } from '../src/types';

export const TemplatePlugin: Plugin = {
  name: 'template',

  beforeBuild(context: BuildContext): void {
    context.engine = new TemplateEngine(context.templatesDir);
    fs.mkdirSync(context.outputDir, { recursive: true });
  },

  onFile(page: Page, context: BuildContext): void {
    const engine = context.engine!;
    const body = engine.renderPage(page);
    const html = engine.renderLayout(page.frontmatter.title, body, page.frontmatter.layout);
    fs.writeFileSync(path.join(context.outputDir, `${page.slug}.html`), html, 'utf-8');
  },

  afterBuild(context: BuildContext): void {
    const engine = context.engine!;
    const indexBody = engine.renderIndex(context.pages);
    const indexHtml = engine.renderLayout('Site Index', indexBody);
    fs.writeFileSync(path.join(context.outputDir, 'index.html'), indexHtml, 'utf-8');
  },
};

import { Plugin, BuildContext } from '../src/plugin';
import { createServer } from '../src/server';

export const DevServerPlugin: Plugin = {
  name: 'devserver',

  async onStart(context: BuildContext): Promise<void> {
    const server = createServer({
      content: context.contentDir,
      output: context.outputDir,
      templates: context.templatesDir,
      port: context.port || 3000,
    });

    await new Promise<void>((resolve, reject) => {
      server.on('error', reject);
      server.listen(context.port || 3000, () => {
        console.log(`Dev server running at http://localhost:${context.port || 3000}`);
        resolve();
      });
    });

    context.server = server;
  },
};

import { SsgConfig } from './src/plugin';

const config: SsgConfig = {
  contentDir: './content',
  outputDir: './dist',
  templatesDir: './templates',
  port: 3000,
};

export default config;

import { Plugin, BuildContext, SsgConfig } from './plugin';
import { Page } from './types';

export class SSG {
  private config: SsgConfig;
  private plugins: Plugin[] = [];

  constructor(config: SsgConfig) {
    this.config = {
      contentDir: config.contentDir || './content',
      outputDir: config.outputDir || './dist',
      templatesDir: config.templatesDir || './templates',
      port: config.port || 3000,
      plugins: config.plugins || [],
    };
  }

  use(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  private async loadPlugins(): Promise<void> {
    if (this.config.plugins) {
      for (const entry of this.config.plugins) {
        if (typeof entry === 'string') {
          try {
            const mod = require(entry);
            const plugin: Plugin = mod.default || mod;
            this.use(plugin);
          } catch {
            continue;
          }
        } else {
          this.use(entry);
        }
      }
    }
  }

  async loadFromConfig(configPath: string): Promise<void> {
    try {
      const mod = require(configPath);
      const externalConfig: SsgConfig = mod.default || mod;
      this.config = {
        ...this.config,
        ...externalConfig,
      };
      await this.loadPlugins();
    } catch {
      // Config file not found or invalid, use defaults
    }
  }

  async build(): Promise<Page[]> {
    await this.loadPlugins();

    const context: BuildContext = {
      config: this.config,
      pages: [],
      contentDir: this.config.contentDir,
      outputDir: this.config.outputDir,
      templatesDir: this.config.templatesDir,
      port: this.config.port,
    };

    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        await plugin.onStart(context);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) {
        await plugin.beforeBuild(context);
      }
    }

    for (const page of context.pages) {
      for (const plugin of this.plugins) {
        if (plugin.onFile) {
          await plugin.onFile(page, context);
        }
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.afterBuild) {
        await plugin.afterBuild(context);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(context);
      }
    }

    return context.pages;
  }

  async serve(): Promise<void> {
    await this.loadPlugins();

    const context: BuildContext = {
      config: this.config,
      pages: [],
      contentDir: this.config.contentDir,
      outputDir: this.config.outputDir,
      templatesDir: this.config.templatesDir,
      port: this.config.port,
    };

    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        await plugin.onStart(context);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(context);
      }
    }
  }
}

